import functools
import inspect
from typing import ForwardRef
from fastapi.dependencies.utils import get_typed_signature, get_typed_return_annotation

# We simulate two different modules by creating separate dictionaries for globals
# and using them to define functions. However, it's easier to just use actual modules.

# Let's create a dummy module for the original function
import types
module_a = types.ModuleType("module_a")
module_a.__dict__["ForwardRef"] = ForwardRef # Ensure ForwardRef is available if needed

class MyModel:
    pass
module_a.__dict__["MyModel"] = MyModel

def original_func(a: "MyModel"):
    return a
original_func.__globals__ = module_a.__dict__
original_func.__annotations__ = {"a": "MyModel"}

# Now create the wrapper in a different "module"
module_b = types.ModuleType("module_b")
def wrapper(a: "MyModel"):
    return original_func(a)
wrapper.__globals__ = module_b.__dict__
wrapper.__annotations__ = {"a": "MyModel"}
wrapper.__wrapped__ = original_func

def test_wrapped_signature():
    # This should not raise NameError because it should use original_func.__globals__
    sig = get_typed_signature(wrapper)
    param = list(sig.parameters.values())[0]
    assert param.annotation is MyModel

def test_wrapped_return_annotation():
    # Setup for return annotation
    def original_func_ret() -> "MyModel":
        return MyModel()
    original_func_ret.__globals__ = module_a.__dict__
    original_func_ret.__annotations__ = {"return": "MyModel"}

    def wrapper_ret():
        return original_func_ret()
    wrapper_ret.__globals__ = module_b.__dict__
    wrapper_ret.__annotations__ = {"return": "MyModel"}
    wrapper_ret.__wrapped__ = original_func_ret

    # This should not raise NameError
    ret_ann = get_typed_return_annotation(wrapper_ret)
    assert ret_ann is MyModel

if __name__ == "__main__":
    try:
        test_wrapped_signature()
        print("test_wrapped_signature passed")
    except Exception as e:
        print(f"test_wrapped_signature failed: {e}")
        import traceback
        traceback.print_exc()

    try:
        test_wrapped_return_annotation()
        print("test_wrapped_return_annotation passed")
    except Exception as e:
        print(f"test_wrapped_return_annotation failed: {e}")
        import traceback
        traceback.print_exc()

